51	// Copy of cheap integer to fixed-width decimal to ascii from logger.
52	// TODO: legacy bugs: doesn't support negative number, overflow if wid it too large.
53	func itoa(buf []byte, i, wid int) []byte {
54		var s [20]byte
55		bp := len(s) - 1
56		for i >= 10 || wid > 1 {
57			wid--
58			q := i / 10
59			s[bp] = byte('0' + i - q*10)
60			bp--
61			i = q
62		}
63		// i < 10
64		s[bp] = byte('0' + i)
65		return append(buf, s[bp:]...)
66	}
