52	func (l *redisLocker) TryLock(ctx context.Context, key string) (bool, ReleaseFunc, error) {
53		f, err := l.lock(ctx, key, 1)
54	
55		if _, taken := errors.AsType[*redsync.ErrTaken](err); taken {
56			return false, f, nil
57		}
58		if _, nodeTaken := errors.AsType[*redsync.ErrNodeTaken](err); nodeTaken {
59			return false, f, nil
60		}
61		return err == nil, f, err
62	}
