64	// Close closes the locker.
65	// It will stop extending the locks and refuse to acquire new locks.
66	// In actual use, it is not necessary to call this function.
67	// But it's useful in tests to release resources.
68	// It could take some time since it waits for the extending goroutine to finish.
69	func (l *redisLocker) Close() error {
70		l.closed.Store(true)
71		l.extendWg.Wait()
72		return nil
73	}
74	
75	func (l *redisLocker) lock(ctx context.Context, key string, tries int) (ReleaseFunc, error) {
76		if l.closed.Load() {
77			return func() {}, errors.New("locker is closed")
78		}
79	
80		options := []redsync.Option{
81			redsync.WithExpiry(redisLockExpiry),
82		}
83		if tries > 0 {
84			options = append(options, redsync.WithTries(tries))
85		}
86		mutex := l.rs.NewMutex(redisLockKeyPrefix+key, options...)
87		if err := mutex.LockContext(ctx); err != nil {
88			return func() {}, err
89		}
90	
91		l.mutexM.Store(key, mutex)
92	
93		releaseOnce := sync.Once{}
94		return func() {
95			releaseOnce.Do(func() {
96				l.mutexM.Delete(key)
97	
98				// It's safe to ignore the error here,
99				// if it failed to unlock, it will be released automatically after the lock expires.
100				// Do not call mutex.UnlockContext(ctx) here, or it will fail to release when ctx has timed out.
101				_, _ = mutex.Unlock()
102			})
103		}, nil
104	}
105	
106	func (l *redisLocker) startExtend() {
107		if l.closed.Load() {
108			l.extendWg.Done()
109			return
110		}
111	
112		toExtend := make([]*redsync.Mutex, 0)
113		l.mutexM.Range(func(_, value any) bool {
114			m := value.(*redsync.Mutex) //nolint:forcetypeassert // mutexM only ever holds *redsync.Mutex
115	
116			// Extend the lock if it is not expired.
117			// Although the mutex will be removed from the map before it is released,
118			// it still can be expired because of a failed extension.
119			// If it happens, it does not need to be extended anymore.
120			if time.Now().After(m.Until()) {
121				return true
122			}
123	
124			toExtend = append(toExtend, m)
125			return true
126		})
127		for _, v := range toExtend {
128			// If it failed to extend, it will be released automatically after the lock expires.
129			_, _ = v.Extend()
130		}
131	
132		time.AfterFunc(redisLockExpiry/2, l.startExtend)
133	}
