14	func newHTTPServer(network, address, name string, handler http.Handler) (*Server, ServeFunction) {
15		server := NewServer(network, address, name)
16		protocols := http.Protocols{}
17		protocols.SetHTTP1(true)
18		protocols.SetHTTP2(true)            // HTTP/2 can only be used when Gitea is configured to use TLS
19		protocols.SetUnencryptedHTTP2(true) // Allow HTTP/2 without TLS, in case Gitea is behind a reverse proxy
20		httpServer := http.Server{
21			Protocols:         &protocols,
22			Handler:           handler,
23			BaseContext:       func(net.Listener) context.Context { return GetManager().HammerContext() },
24			ReadHeaderTimeout: 10 * time.Second,
25		}
26		server.OnShutdown = func() {
27			httpServer.SetKeepAlivesEnabled(false)
28		}
29		return server, httpServer.Serve
