36	// gitProxySelector picks proxies like git did: [git.config] http.proxy, else a [proxy] PROXY_URL, else the environment incl. ALL_PROXY
37	func gitProxySelector() (func(*http.Request) (*url.URL, error), error) {
38		env := httpproxy.FromEnvironment()
39		if rawURL, ok := setting.GitConfig.Options["http.proxy"]; ok {
40			gitProxy, err := normalizeGitProxy(rawURL)
41			if err != nil {
42				return nil, fmt.Errorf("[git.config] http.proxy: %w", err)
43			}
44			env.HTTPProxy, env.HTTPSProxy = gitProxy, gitProxy
45			return requestProxy(env), nil
46		}
47		if setting.Proxy.Enabled && setting.Proxy.ProxyURL != "" {
48			return proxy.Proxy(), nil
49		}
50		allProxy := cmp.Or(os.Getenv("all_proxy"), os.Getenv("ALL_PROXY"))
51		env.HTTPProxy, env.HTTPSProxy = cmp.Or(env.HTTPProxy, allProxy), cmp.Or(env.HTTPSProxy, allProxy)
52		return requestProxy(env), nil
53	}
