55	func requestProxy(cfg *httpproxy.Config) func(*http.Request) (*url.URL, error) {
56		proxyFunc := cfg.ProxyFunc()
57		return func(req *http.Request) (*url.URL, error) { return proxyFunc(req.URL) }
58	}
