60	// normalizeGitProxy reads a proxy URL the way git reads http.proxy: http is the default scheme, 1080 curl's default port
61	func normalizeGitProxy(rawURL string) (string, error) {
62		if rawURL == "" {
63			return "", nil
64		}
65		if !strings.Contains(rawURL, "://") {
66			rawURL = "http://" + rawURL
67		}
68		proxyURL, err := url.Parse(rawURL)
69		if err != nil {
70			return "", errors.New("invalid URL") // the parse error would echo its credentials
71		}
72		if proxyURL.Scheme == "http" && proxyURL.Port() == "" {
73			proxyURL.Host = net.JoinHostPort(proxyURL.Hostname(), "1080")
74		}
75		return proxyURL.String(), nil
76	}
