78	func newMigrationPolicy(selectProxy func(*http.Request) (*url.URL, error)) *policy.Policy {
79		return policy.NewPolicy("migrations", policyMode(setting.Migrations.EgressMode),
80			policy.WithAllow(setting.Migrations.AllowedHostList, "migrations.ALLOWED_HOST_LIST"),
81			policy.WithBlock(setting.Migrations.BlockedHostList, "migrations.BLOCKED_HOST_LIST"),
82			policy.WithLocalNeedsIPAllow(),
83			policy.WithProxy(selectProxy))
