86	func NewWebhookPolicy() *policy.Policy {
87		var p *policy.Policy
88		selectProxy := proxy.WebHookProxy()
89		if webhookProxy := setting.Webhook.ProxyURLFixed; webhookProxy != nil {
90			next := selectProxy
91			selectProxy = func(req *http.Request) (*url.URL, error) {
92				u, err := next(req)
93				if err == nil && u == webhookProxy {
94					err = p.CheckHost(req.URL) // the webhook proxy resolves the target, so only its name can be checked
95				}
96				return u, err
97			}
98		}
99		p = policy.NewPolicy("webhook", policyMode(setting.Security.EgressMode),
100			policy.WithAllow(setting.Webhook.AllowedHostList, "security.ALLOWED_HOST_LIST"),
101			policy.WithLocalNeedsIPAllow(),
102			policy.WithProxy(selectProxy))
103	
104		return p
105	}
